using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Globalization;using Frociart;
internal static class FprgExtendedTests {
 static int checks;static void Check(bool v,string s){if(!v)throw new Exception(s);checks++;}static string Text(string v){return(string)ExpressionLanguage.Evaluate(v,null);}static string Normalize(string v){return v.Replace("\r\n","\n");}static double Num(string v){return Double.Parse(v,CultureInfo.InvariantCulture);}static bool Near(double a,double b){return Math.Abs(a-b)<.000001;}static string Enc(Diagram d){return Convert.ToBase64String(DiagramIO.EncodeDocument(d));}
 static Interpreter Execute(Diagram d,string[] row){var r=new Interpreter(d);var writes=new List<string>();int reads=0;for(int i=0;i<3000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++){if(r.State==RuntimeState.WaitingForFile){var req=r.PendingFile;Check(r.FileDeferred(req,"Riprovare"),"Deferred request retained");Check(Object.ReferenceEquals(req,r.PendingFile),"Deferral preserves capability");if(req.Kind==FlowFileRequestKind.Read){reads++;Check(!r.Files.HasRead,"No input before host grant");Check(r.ProvideFile(req,Text(row[2])),"Read capability fulfilled");}else{writes.Add(Normalize(req.Text));Check(r.Files.OutputDraft==req.Text,"Save sees exact recoverable draft");Check(r.ProvideFile(req),"Save acknowledged");}Check(!r.ProvideFile(req,"stale"),"Stale capability rejected");}else r.Step();}
  Check(r.State==RuntimeState.Completed,"Runtime completes "+row[0]+": "+r.Error);Check(Normalize(r.OutputText)==Text(row[1]),"Console exact "+row[0]);Check(reads==Int32.Parse(row[9])&&writes.Count==Int32.Parse(row[10]),"Exact read/save counts");if(writes.Count>0)Check(String.Join("",writes)==Text(row[3]),"File content exact");Check(Near(r.Turtle.X,Num(row[4]))&&Near(r.Turtle.Y,Num(row[5]))&&Near(r.Turtle.Heading,Num(row[6])),"Turtle position and heading exact");Check(r.Turtle.Color==row[8]&&r.Turtle.Segments.Count==Int32.Parse(row[7]),"Colour and line count exact");string[] lines=row[11].Length==0?new string[0]:row[11].Split(';');for(int i=0;i<lines.Length;i++){string[] p=lines[i].Split(',');var s=r.Turtle.Segments[i];Check(Near(s.X1,Num(p[0]))&&Near(s.Y1,Num(p[1]))&&Near(s.X2,Num(p[2]))&&Near(s.Y2,Num(p[3]))&&s.Color==p[4],"Every segment exact");}return r;
 }
 [STAThread]static int Main(string[] args){try{string root=args[0];Directory.CreateDirectory(Path.Combine(root,"pc"));foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"),Encoding.UTF8)){string[] row=line.Split('\t');string path=Path.Combine(root,"fixtures",row[0]+".fprg");byte[] original=File.ReadAllBytes(path);var d=DiagramIO.Load(path);string before=Enc(d);Execute(d,row);Check(Enc(d)==before&&original.SequenceEqual(File.ReadAllBytes(path)),"Execution leaves both project and source file unchanged");Execute(DiagramIO.Clone(d),row);Execute(FlowPseudocode.Decode(FlowPseudocode.Encode(d)),row);string saved=Path.Combine(root,"pc",row[0]+".frociart");DiagramIO.Save(saved,d);Execute(DiagramIO.Load(saved),row);Execute(FlowClipboard.Decode(FlowClipboard.Encode(d)),row);Check(!Encoding.UTF8.GetString(DiagramIO.EncodeDocument(d)).Contains("PRIVATE_"),"Metadata absent");FlowSource.Compile(d);Check(FlowPython.Generate(FlowSource.Compile(d)).Text.Length>0,"Python source accepts imported nodes");}
  foreach(string file in Directory.GetFiles(Path.Combine(root,"fixtures"),"reject-*.fprg")){bool rejected=false;try{DiagramIO.Load(file);}catch(InvalidDataException e){rejected=e.Message.Contains("Flowgorithm");}Check(rejected,"Atomic diagnostic rejects "+Path.GetFileName(file));}
  string canary=Path.Combine(root,"never-auto-open.txt");File.WriteAllText(canary,"PRIVATE_CANARY");string xml="<flowgorithm fileversion=\"4.2\"><function name=\"Main\" type=\"None\" variable=\"\"><parameters/><body><open mode=\"read\" expression=\"&quot;"+System.Security.SecurityElement.Escape(Path.GetFullPath(canary))+"&quot;\"/></body></function></flowgorithm>";var guarded=FlowgorithmImport.DecodeText(xml);var runner=new Interpreter(guarded);for(int i=0;i<8&&runner.State!=RuntimeState.WaitingForFile;i++)runner.Step();Check(runner.State==RuntimeState.WaitingForFile&&!runner.Files.HasRead,"Imported path cannot open file without host capability");Check(File.ReadAllText(canary)=="PRIVATE_CANARY","Canary untouched");
  Console.WriteLine("FPRG_EXTENDED_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
